from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.gnb.gnb import ClassicalBts, CloudBts


class _PduWrapper(object):
    def __init__(self, pdu_port):
        self._pdu_port = pdu_port

    @property
    def port(self):
        return self._pdu_port.port_no

    @property
    def addr(self):
        return self._pdu_port.pdu.addr

    @property
    def device(self):
        return self._pdu_port.pdu.__class__.__name__.upper()


class _RFWrapper(ListAbstractionsWrapper):
    """
    All redirection for rf are contained inside this wrapper's properties
    """
    def __init__(self, tl_config):
        super(_RFWrapper, self).__init__(tl_config)

    def _get_classical_bts_du(self):
        return self.get_instance(ClassicalBts, self.tl_config.gnbs).du

    def _get_cloud_bts_du(self):
        return self.get_instance(CloudBts, self.tl_config.gnbs).dus[0]

    @property
    def pdu(self):
        try:
            return _PduWrapper(self._get_cloud_bts_du().rus[0].pdu_port)
        except AttributeError:
            return _PduWrapper(self._get_classical_bts_du().rus[0].pdu_port)
